//! Funding occurrences and source-scoped funder observations.

use chrono::{DateTime, NaiveDate, Utc};
use serde::Serialize;
use uuid::Uuid;

use super::{
    declaration_ingestion::{CapturedDeclaration, CapturedFundingEntry, DeclarationId, MemberAsId},
    entity_ingestion::EntityIngestionError,
    funder_name::FunderNameFeatures,
};

/// One existing member's replayed source declarations.
pub enum CapturedMemberDeclarations {
    /// An empty member partition has no projected Parliament identity.
    Empty {
        /// Stored member UUID from the partition filename.
        member_id: Uuid,
    },
    /// A populated member partition with checked identities.
    Populated {
        /// Stored member identity from the raw partition.
        member: MemberAsId,
        /// Unique declarations in deterministic source-ID order.
        declarations: Vec<DeclarationEvidence>,
    },
}

/// Top-level names not represented by a top-level funding occurrence.
#[derive(Debug)]
pub struct DeclarationFunderNames {
    /// Explicit donor name.
    pub donor_name: Option<String>,
    /// Explicit payer name.
    pub payer_name: Option<String>,
    /// Explicit ultimate payer name.
    pub ultimate_payer_name: Option<String>,
    /// Source donor kind, without inference.
    pub donor_kind: Option<String>,
    /// Source donor company identifier, without inference.
    pub donor_company_number: Option<String>,
}

/// Replayed evidence with source-JSON pointers for each occurrence.
pub struct DeclarationEvidence {
    pub(crate) declaration: CapturedDeclaration,
    pub(crate) declaration_funders: Option<DeclarationFunderNames>,
    pub(crate) declaration_source_pointer: String,
    funding_source_pointers: Vec<String>,
}

impl DeclarationEvidence {
    /// Associates a parsed declaration with pointers to its source fields.
    ///
    /// # Errors
    /// Rejects a different number of funding occurrences and source pointers.
    pub fn new(
        declaration: CapturedDeclaration,
        declaration_funders: Option<DeclarationFunderNames>,
        declaration_source_pointer: String,
        funding_source_pointers: Vec<String>,
    ) -> Result<Self, EntityIngestionError> {
        if declaration.funding_entries().len() != funding_source_pointers.len() {
            return Err(EntityIngestionError::DataError(
                "funding source pointers do not match occurrences".into(),
            ));
        }
        Ok(Self {
            declaration,
            declaration_funders,
            declaration_source_pointer,
            funding_source_pointers,
        })
    }

    /// Captured projection used to check the existing raw rows.
    #[must_use]
    pub const fn declaration(&self) -> &CapturedDeclaration {
        &self.declaration
    }

    fn funding_occurrences(&self) -> impl Iterator<Item = (&CapturedFundingEntry, &str)> {
        self.declaration
            .funding_entries()
            .iter()
            .zip(self.funding_source_pointers.iter().map(String::as_str))
    }
}

/// Stable source occurrence identity, independent of name features.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize)]
#[serde(transparent)]
pub struct FundingEntryId(String);

/// Stable source-role observation identity, independent of name features.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize)]
#[serde(transparent)]
pub struct FunderObservationId(String);

/// Role explicitly named by the source.
#[derive(Clone, Copy, Debug, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum FunderRole {
    /// Donor, the owner of donor-kind and company-number evidence.
    Donor,
    /// Payer, without assumed donor metadata.
    Payer,
    /// Ultimate payer, without assumed donor metadata.
    UltimatePayer,
}

impl FunderRole {
    const fn suffix(self) -> &'static str {
        match self {
            Self::Donor => "donor",
            Self::Payer => "payer",
            Self::UltimatePayer => "ultimate_payer",
        }
    }
}

/// Whether a named role belongs to a declaration or one funding occurrence.
#[derive(Debug, Serialize)]
#[serde(tag = "source_scope", rename_all = "snake_case")]
pub enum FunderObservationSource {
    /// A declaration-level scope with no top-level funding anchor.
    Declaration {
        /// JSON pointer into the retained declaration source.
        source_pointer: String,
    },
    /// One actual funding occurrence, including repeated identical entries.
    FundingEntry {
        /// Identity of the containing funding occurrence.
        funding_entry_id: FundingEntryId,
        /// Zero-based position in the replayed funding list.
        funding_ordinal: u32,
        /// JSON pointer into the retained declaration source.
        source_pointer: String,
    },
}

/// A source role and its parallel name features, without an entity-identity claim.
#[derive(Debug, Serialize)]
pub struct FunderObservation {
    pub(crate) funder_id: FunderObservationId,
    pub(crate) member_id: String,
    pub(crate) declaration_id: u32,
    pub(crate) register_id: u32,
    pub(crate) role: FunderRole,
    #[serde(flatten)]
    pub(crate) source: FunderObservationSource,
    pub(crate) donor_kind: Option<String>,
    pub(crate) donor_company_number: Option<String>,
    #[serde(flatten)]
    pub(crate) name: FunderNameFeatures,
}

/// One source funding occurrence with all original values and role references.
#[derive(Debug, Serialize)]
pub struct CleanedFundingEntry {
    pub(crate) funding_entry_id: FundingEntryId,
    pub(crate) member_id: String,
    pub(crate) parliament_member_id: u32,
    pub(crate) declaration_id: u32,
    pub(crate) register_id: u32,
    pub(crate) funding_ordinal: u32,
    pub(crate) parent_declaration_id: Option<u32>,
    pub(crate) category_id: u32,
    pub(crate) category_name: String,
    pub(crate) register_published_date: NaiveDate,
    pub(crate) registration_date: Option<NaiveDate>,
    pub(crate) fetched_at: DateTime<Utc>,
    pub(crate) donor_funder_id: Option<FunderObservationId>,
    pub(crate) payer_funder_id: Option<FunderObservationId>,
    pub(crate) ultimate_payer_funder_id: Option<FunderObservationId>,
    #[serde(flatten)]
    pub(crate) funding: CapturedFundingEntry,
}

/// Counts of the captured evidence processed by an offline clean operation.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DeclarationCleaningSummary {
    /// Number of raw member partitions, including empty partitions.
    pub member_partitions: usize,
    /// Number of declarations, including those with no funding.
    pub declarations: usize,
    /// Number of actual funding occurrences.
    pub funding_entries: usize,
    /// Number of source-role observations across both scopes.
    pub funders: usize,
}

/// A coherent pair of tables constructed together by the cleaning transform.
pub struct CleanedDeclarations {
    pub(crate) funding_entries: Vec<CleanedFundingEntry>,
    pub(crate) funders: Vec<FunderObservation>,
    summary: DeclarationCleaningSummary,
}

impl CleanedDeclarations {
    /// Counts derived from the constructed tables and their input evidence.
    #[must_use]
    pub const fn summary(&self) -> &DeclarationCleaningSummary {
        &self.summary
    }

    /// Separates occurrences and observations without merging names or attributing parents.
    ///
    /// # Errors
    /// Returns an error if a source declaration has more than `u32::MAX` funding entries.
    pub fn from_captures(
        captures: &[CapturedMemberDeclarations],
    ) -> Result<Self, EntityIngestionError> {
        let mut funding_entries = Vec::new();
        let mut funders = Vec::new();
        let mut declaration_count = 0;
        for capture in captures {
            let CapturedMemberDeclarations::Populated {
                member,
                declarations,
            } = capture
            else {
                continue;
            };
            declaration_count += declarations.len();
            for evidence in declarations {
                let declaration = &evidence.declaration;
                let scope_id = format!(
                    "{}/{}/{}",
                    member.member_id(),
                    declaration.id().value(),
                    declaration.register_id()
                );
                if let Some(names) = &evidence.declaration_funders {
                    let source = || FunderObservationSource::Declaration {
                        source_pointer: evidence.declaration_source_pointer.clone(),
                    };
                    add_roles(
                        &mut funders,
                        *member,
                        declaration,
                        &format!("{scope_id}/declaration"),
                        source,
                        names.donor_name.as_deref(),
                        names.payer_name.as_deref(),
                        names.ultimate_payer_name.as_deref(),
                        names.donor_kind.as_deref(),
                        names.donor_company_number.as_deref(),
                    );
                }
                for (ordinal, (funding, pointer)) in evidence.funding_occurrences().enumerate() {
                    let ordinal = u32::try_from(ordinal)
                        .map_err(|error| EntityIngestionError::DataError(error.to_string()))?;
                    let id = FundingEntryId(format!("{scope_id}/funding/{ordinal}"));
                    let source = || FunderObservationSource::FundingEntry {
                        funding_entry_id: id.clone(),
                        funding_ordinal: ordinal,
                        source_pointer: pointer.to_owned(),
                    };
                    let [donor, payer, ultimate] = add_roles(
                        &mut funders,
                        *member,
                        declaration,
                        &id.0,
                        source,
                        funding.donor_name(),
                        funding.payer_name(),
                        funding.ultimate_payer_name(),
                        funding.funder_kind(),
                        funding.company_number(),
                    );
                    funding_entries.push(CleanedFundingEntry {
                        funding_entry_id: id,
                        member_id: member.member_id().to_string(),
                        parliament_member_id: member.parliament_member_id(),
                        declaration_id: declaration.id().value(),
                        register_id: declaration.register_id(),
                        funding_ordinal: ordinal,
                        parent_declaration_id: declaration.parent_id().map(DeclarationId::value),
                        category_id: declaration.category_id(),
                        category_name: declaration.category_name().to_owned(),
                        register_published_date: declaration.register_published_date(),
                        registration_date: declaration.registration_date(),
                        fetched_at: declaration.fetched_at(),
                        donor_funder_id: donor,
                        payer_funder_id: payer,
                        ultimate_payer_funder_id: ultimate,
                        funding: funding.clone(),
                    });
                }
            }
        }
        let summary = DeclarationCleaningSummary {
            member_partitions: captures.len(),
            declarations: declaration_count,
            funding_entries: funding_entries.len(),
            funders: funders.len(),
        };
        Ok(Self {
            funding_entries,
            funders,
            summary,
        })
    }
}

#[allow(clippy::too_many_arguments)]
fn add_roles(
    funders: &mut Vec<FunderObservation>,
    member: MemberAsId,
    declaration: &CapturedDeclaration,
    scope_id: &str,
    source: impl Fn() -> FunderObservationSource,
    donor: Option<&str>,
    payer: Option<&str>,
    ultimate: Option<&str>,
    kind: Option<&str>,
    company: Option<&str>,
) -> [Option<FunderObservationId>; 3] {
    [
        (FunderRole::Donor, donor, kind, company),
        (FunderRole::Payer, payer, None, None),
        (FunderRole::UltimatePayer, ultimate, None, None),
    ]
    .map(|(role, name, kind, company)| {
        if name.is_none() && kind.is_none() && company.is_none() {
            return None;
        }
        let id = FunderObservationId(format!("{scope_id}/{}", role.suffix()));
        funders.push(FunderObservation {
            funder_id: id.clone(),
            member_id: member.member_id().to_string(),
            declaration_id: declaration.id().value(),
            register_id: declaration.register_id(),
            role,
            source: source(),
            donor_kind: kind.map(str::to_owned),
            donor_company_number: company.map(str::to_owned),
            name: FunderNameFeatures::from_name(name),
        });
        Some(id)
    })
}
//! Parallel name features for later entity resolution, without identity decisions.

use serde::Serialize;
use unicode_normalization::{UnicodeNormalization, char::is_combining_mark};

/// Whether the source supplies a usable name.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum NameStatus {
    /// A nonempty name, retained without guessing its entity type.
    Present,
    /// No name or only whitespace.
    Missing,
    /// An explicit confidentiality or anonymity placeholder.
    Withheld,
}

/// Independent candidate representations, never keys for merging observations.
#[derive(Debug, Serialize)]
pub struct FunderNameFeatures {
    /// Original source spelling, including placeholders and whitespace.
    pub name_raw: Option<String>,
    /// Explicit absence or withholding classification.
    pub name_status: NameStatus,
    /// NFKC, lowercase, and collapsed whitespace.
    pub name_normalized: Option<String>,
    /// Normalized name with decomposed combining marks removed.
    pub name_accent_folded: Option<String>,
    /// Punctuation-normalized tokens in source order.
    pub name_tokens: Option<String>,
    /// Sorted tokens, retaining repeated words.
    pub name_token_key: Option<String>,
    /// Normalized primary name without explicit trading-as text.
    pub primary_name_normalized: Option<String>,
    /// Primary-name tokens without an explicit UK legal suffix.
    pub organisation_core: Option<String>,
    /// Token sequence without common leading honorifics.
    pub person_core: Option<String>,
    /// Initial letters of the person-core tokens.
    pub person_initials: Option<String>,
    /// Organisation-core initials, excluding listed connective words.
    pub organisation_initials: Option<String>,
    /// A source acronym whose letters agree with an explicit parenthetical expansion.
    pub explicit_acronym: Option<String>,
    /// Normalized expansion validated against the explicit acronym.
    pub acronym_expansion_normalized: Option<String>,
    /// Parenthetical contents in their original spelling and order.
    pub parenthetical_text: Vec<String>,
    /// Names following an explicit trading-as marker, without inferred aliases.
    pub explicit_aliases: Vec<String>,
    /// Normalized forms of those explicit aliases, in the same order.
    pub alias_normalized: Vec<String>,
    /// Literal `and` or ampersand evidence, without claiming multiple entities.
    pub has_conjunction: bool,
    /// At least one unmatched opening or closing parenthesis.
    pub has_unbalanced_parentheses: bool,
}

impl FunderNameFeatures {
    /// Derives parallel features while retaining the original evidence.
    #[must_use]
    pub fn from_name(raw: Option<&str>) -> Self {
        let normalized = raw.map(normalize);
        let name_status = match normalized.as_deref() {
            None | Some("") => NameStatus::Missing,
            Some("confidential" | "withheld" | "name withheld" | "anonymous" | "not disclosed") => {
                NameStatus::Withheld
            }
            Some(_) => NameStatus::Present,
        };
        let (parenthetical_text, has_unbalanced_parentheses) = parentheses(raw.unwrap_or(""));
        let usable = normalized.filter(|_| name_status == NameStatus::Present);
        let name_accent_folded = usable.as_ref().map(|name| {
            name.nfd()
                .filter(|c| !is_combining_mark(*c))
                .collect::<String>()
        });
        let name_tokens = usable.as_deref().map(tokens);
        let has_conjunction = name_tokens
            .as_deref()
            .is_some_and(|name| name.split_whitespace().any(|word| word == "and"));
        let name_token_key = name_tokens.as_deref().map(|name| {
            let mut words = name.split_whitespace().collect::<Vec<_>>();
            words.sort_unstable();
            words.join(" ")
        });
        let primary_name_normalized = raw
            .filter(|_| name_status == NameStatus::Present)
            .map(|raw| normalize(&primary_name(raw)));
        let organisation_core = primary_name_normalized
            .as_deref()
            .map(|name| organisation_core(&tokens(name)));
        let person_core = name_tokens.as_deref().map(person_core);
        let person_initials = person_core.as_deref().map(|name| initials(name, false));
        let organisation_initials = organisation_core
            .as_deref()
            .map(|name| initials(name, true));
        let (explicit_acronym, acronym_expansion_normalized) = raw
            .and_then(|name| explicit_acronym(name, &parenthetical_text))
            .unzip();
        let explicit_aliases = raw.map_or_else(Vec::new, |name| aliases(name, &parenthetical_text));
        let alias_normalized = explicit_aliases
            .iter()
            .map(|name| normalize(name))
            .collect();
        Self {
            name_raw: raw.map(str::to_owned),
            name_status,
            name_normalized: usable,
            name_accent_folded,
            name_tokens,
            name_token_key,
            primary_name_normalized,
            organisation_core,
            person_core,
            person_initials,
            organisation_initials,
            explicit_acronym,
            acronym_expansion_normalized,
            parenthetical_text,
            explicit_aliases,
            alias_normalized,
            has_conjunction,
            has_unbalanced_parentheses,
        }
    }
}

fn normalize(raw: &str) -> String {
    raw.nfkc()
        .flat_map(char::to_lowercase)
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

fn tokens(name: &str) -> String {
    let mut result = String::new();
    for word in name.split_whitespace() {
        let acronym = word.trim_matches(|c: char| !c.is_alphanumeric() && c != '.');
        let dotted_acronym = acronym.contains('.')
            && acronym.trim_end_matches('.').split('.').all(|part| {
                let mut letters = part.chars();
                letters.next().is_some_and(char::is_alphabetic) && letters.next().is_none()
            });
        for c in word.chars() {
            match c {
                '&' => result.push_str(" and "),
                '\'' | '\u{2019}' | '\u{2018}' | '\u{02bc}' => {}
                '.' if dotted_acronym => {}
                c if c.is_alphanumeric() || is_combining_mark(c) => result.push(c),
                _ => result.push(' '),
            }
        }
        result.push(' ');
    }
    result.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn organisation_core(name: &str) -> String {
    const SUFFIXES: &[&[&str]] = &[
        &["public", "limited", "company"],
        &["community", "interest", "company"],
        &["limited", "liability", "partnership"],
        &["limited", "partnership"],
        &["limited"],
        &["ltd"],
        &["plc"],
        &["llp"],
        &["lp"],
        &["cic"],
    ];
    let mut words = name.split_whitespace().collect::<Vec<_>>();
    if let Some(suffix) = SUFFIXES.iter().find(|suffix| words.ends_with(suffix)) {
        words.truncate(words.len() - suffix.len());
    }
    words.join(" ")
}

fn person_core(name: &str) -> String {
    const TITLES: &[&str] = &[
        "mr",
        "mrs",
        "ms",
        "miss",
        "mx",
        "dr",
        "prof",
        "professor",
        "sir",
        "dame",
        "lord",
        "lady",
        "rev",
        "reverend",
        "rt",
        "hon",
    ];
    name.split_whitespace()
        .skip_while(|word| TITLES.contains(word))
        .collect::<Vec<_>>()
        .join(" ")
}

fn initials(name: &str, omit_connectives: bool) -> String {
    const CONNECTIVES: &[&str] = &["a", "an", "and", "for", "in", "of", "on", "the", "to"];
    name.split_whitespace()
        .filter(|word| !omit_connectives || !CONNECTIVES.contains(word))
        .filter_map(|word| word.chars().next())
        .collect()
}

fn parentheses(raw: &str) -> (Vec<String>, bool) {
    let mut result = Vec::new();
    let mut depth = 0;
    let mut start = 0;
    let mut unbalanced = false;
    for (index, c) in raw.char_indices() {
        match c {
            '(' => {
                if depth == 0 {
                    start = index + 1;
                }
                depth += 1;
            }
            ')' if depth > 0 => {
                depth -= 1;
                if depth == 0 {
                    result.push(raw[start..index].to_owned());
                }
            }
            ')' => unbalanced = true,
            _ => {}
        }
    }
    if depth > 0 {
        result.push(raw[start..].to_owned());
    }
    (result, unbalanced || depth > 0)
}

fn explicit_acronym(raw: &str, parenthetical: &[String]) -> Option<(String, String)> {
    let before = raw.split('(').next()?.trim();
    for expansion in parenthetical {
        for (candidate, full) in [(before, expansion.as_str()), (expansion.as_str(), before)] {
            let letters = candidate
                .chars()
                .filter(|c| *c != '.' && !c.is_whitespace())
                .collect::<String>();
            if (2..=10).contains(&letters.chars().count())
                && letters.chars().all(|c| c.is_ascii_uppercase())
                && letters.to_lowercase() == initials(&tokens(&normalize(full)), true)
            {
                return Some((letters.to_lowercase(), normalize(full)));
            }
        }
    }
    None
}

fn alias_marker(candidate: &str, top_level_only: bool) -> Option<(usize, usize)> {
    let lower = candidate.to_ascii_lowercase();
    let mut found = None;
    for marker in ["trading as", "t/a"] {
        for (index, _) in lower.match_indices(marker) {
            let boundary = (index == 0 || lower[..index].ends_with([' ', '(', ',']))
                && lower[index + marker.len()..].starts_with(char::is_whitespace);
            let depth = candidate[..index].chars().fold(0_i32, |depth, c| match c {
                '(' => depth + 1,
                ')' => depth - 1,
                _ => depth,
            });
            if boundary
                && (!top_level_only || depth == 0)
                && found.is_none_or(|(previous, _)| index < previous)
            {
                found = Some((index, marker.len()));
            }
        }
    }
    found
}

fn aliases(raw: &str, parenthetical: &[String]) -> Vec<String> {
    let mut result = Vec::new();
    for (candidate, top_level_only) in parenthetical
        .iter()
        .map(|name| (name.as_str(), false))
        .chain(std::iter::once((raw, true)))
    {
        if let Some((index, length)) = alias_marker(candidate, top_level_only) {
            let alias = candidate[index + length..].trim().to_owned();
            if !alias.is_empty() && !result.contains(&alias) {
                result.push(alias);
            }
        }
    }
    result
}

fn primary_name(raw: &str) -> String {
    let mut result = String::new();
    let mut depth = 0;
    let mut start = 0;
    let mut keep_from = 0;
    for (index, c) in raw.char_indices() {
        match c {
            '(' => {
                if depth == 0 {
                    start = index;
                }
                depth += 1;
            }
            ')' if depth > 0 => {
                depth -= 1;
                if depth == 0 && alias_marker(&raw[start + 1..index], false).is_some() {
                    result.push_str(&raw[keep_from..start]);
                    result.push(' ');
                    keep_from = index + 1;
                }
            }
            _ => {}
        }
    }
    result.push_str(&raw[keep_from..]);
    if let Some((index, _)) = alias_marker(&result, true) {
        result.truncate(index);
    }
    result.trim().trim_end_matches(',').trim().to_owned()
}

