 39	impl DeclarationCleaningStorage for ExposedDataPipeline {
 40	    async fn read_captured_declarations(
 41	        &self,
 42	    ) -> Result<Vec<CapturedMemberDeclarations>, EntitySearchPipelineError> {
 43	        if fs::try_exists(self.cleaned_declarations_path())
 44	            .await
 45	            .map_err(read_error)?
 46	        {
 47	            return Err(write_error("cleaned declarations already exist"));
 48	        }
 49	        let directory = self.raw_path().join("declarations");
 50	        let mut files = fs::read_dir(&directory).await.map_err(read_error)?;
 51	        let mut paths = Vec::new();
 52	        while let Some(file) = files.next_entry().await.map_err(read_error)? {
 53	            let path = file.path();
 54	            if path
 55	                .extension()
 56	                .is_some_and(|extension| extension == "parquet")
 57	            {
 58	                paths.push(path);
 59	            }
 60	        }
 61	        paths.sort();
 62	        if paths.is_empty() {
 63	            return Err(read_error("no raw declaration partitions found"));
 64	        }
 65	        paths
 66	            .into_iter()
 67	            .map(|path| {
 68	                read_partition(&path)
 69	                    .map_err(|error| read_error(format!("{}: {error}", path.display())))
 70	            })
 71	            .collect()
 72	    }
 73	
 74	    async fn publish_cleaned_declarations(
 75	        &self,
 76	        cleaned: &CleanedDeclarations,
 77	    ) -> Result<(), EntitySearchPipelineError> {
 78	        let destination = self.cleaned_declarations_path();
 79	        if fs::try_exists(&destination).await.map_err(write_error)? {
 80	            return Err(write_error("cleaned declarations already exist"));
 81	        }
 82	        let parent = destination
 83	            .parent()
 84	            .expect("cleaned declarations have a parent");
 85	        fs::create_dir_all(parent).await.map_err(write_error)?;
 86	        let staging = parent.join(format!(".declarations-{}", Uuid::now_v7()));
 87	        fs::create_dir(&staging).await.map_err(write_error)?;
 88	        let result = async {
 89	            write_table(
 90	                &staging.join("funding_entries.parquet"),
 91	                funding_schema(),
 92	                &cleaned.funding_entries,
 93	            )
 94	            .await?;
 95	            write_table(
 96	                &staging.join("funders.parquet"),
 97	                funders_schema(),
 98	                &cleaned.funders,
 99	            )
100	            .await?;
101	            fs::rename(&staging, &destination)
102	                .await
103	                .map_err(write_error)
104	        }
105	        .await;
106	        if result.is_err() {
107	            let _ = fs::remove_dir_all(&staging).await;
108	        }
109	        result
110	    }
