 54	/// Entry point for CLI commands
 55	///
 56	/// # Errors
 57	/// - Bad stage arg
 58	/// - Bad config path
 59	/// - Bad config shape
 60	/// - Missing or non-Unicode `DATABASE_URL` for commands that use the database
 61	/// - Service level failures
 62	pub async fn run_cli(args: DataArgs) -> anyhow::Result<()> {
 63	    match args.command {
 64	        DataCommands::Latest { config } => {
 65	            let config = LoaderConfig::try_from(&config)?;
 66	            match ExposedDataPipeline::latest_ingestion(&config.data_dir).await? {
 67	                Some((path, key)) => {
 68	                    println!("Ingestion key: {key}");
 69	                    println!("Path: {}", path.display());
 70	                }
 71	                None => println!("No ingestion runs found."),
 72	            }
 73	        }
 74	        DataCommands::Declarations {
 75	            stage,
 76	            config,
 77	            ingestion_key,
 78	        } => match DeclarationIngestionStage::from_str(&stage)? {
 79	            DeclarationIngestionStage::Fetch => {
 80	                let config = DeclarationFetcherConfig::try_from(&config)?;
 81	                let data_config = DataConfig::from_env()?;
 82	                let api = ParliamentApiClient::new(config.batch_size)?;
 83	                let db = ExposedDatabase::new(&data_config.connection_string).await;
 84	                let fs = ExposedDataPipeline::new_with_ingestion_key(
 85	                    &config.data_dir,
 86	                    ingestion_key.unwrap_or_default(),
 87	                )?;
 88	                DeclarationFetcherService::new(db, api, fs)
 89	                    .fetch_declarations()
 90	                    .await?;
 91	            }
 92	            DeclarationIngestionStage::Clean => {
 93	                let ingestion_key = ingestion_key.ok_or_else(|| {
 94	                    anyhow::anyhow!("declarations clean requires --ingestion-key")
 95	                })?;
 96	                let config = LoaderConfig::try_from(&config)?;
 97	                let fs = ExposedDataPipeline::open_existing_declarations(
 98	                    &config.data_dir,
 99	                    ingestion_key.clone(),
100	                )?;
101	                let summary = DeclarationCleanerService::new(fs)
102	                    .clean_declarations()
103	                    .await?;
104	                println!("Ingestion key: {ingestion_key}");
105	                println!(
106	                    "Cleaned declarations: {}",
107	                    std::path::absolute(&config.data_dir)?
108	                        .join(ingestion_key.to_string())
109	                        .join("cleaned/declarations")
110	                        .display()
111	                );
112	                println!("Member partitions: {}", summary.member_partitions);
113	                println!("Declarations: {}", summary.declarations);
114	                println!("Funding entries: {}", summary.funding_entries);
115	                println!("Funder observations: {}", summary.funders);
116	            }
117	        },
118	        DataCommands::Members {
119	            stage,
120	            config,
121	            ingestion_key,
122	        } => {
123	            let stage = MemberIngestionStage::from_str(&stage)?;
124	            let ingestion_key = ingestion_key.unwrap_or_default();
125	            match stage {
126	                MemberIngestionStage::Fetch => {
127	                    let config = FetcherConfig::try_from(&config)?;
128	                    let api = ParliamentApiClient::new(config.batch_size)?;
129	                    let fs = ExposedDataPipeline::new_with_ingestion_key(
130	                        &config.data_dir,
131	                        ingestion_key,
132	                    )?;
133	                    let service = FetcherService::new(fs, api);
134	
135	                    let req = EntityIngestionRequest {};
136	                    service.fetch_members(&req).await?;
137	                }
138	                MemberIngestionStage::Load => {
139	                    let config = LoaderConfig::try_from(&config)?;
140	                    let data_config = DataConfig::from_env()?;
141	                    let fs = ExposedDataPipeline::new_with_ingestion_key(
142	                        &config.data_dir,
143	                        ingestion_key,
144	                    )?;
145	                    let db = ExposedDatabase::new(&data_config.connection_string).await;
146	                    let service = IngesterService::new(fs, db);
147	
148	                    service.load_members().await?;
149	                }
150	            }
151	        }
152	    }
153	    Ok(())
154	}
