    74	    async fn publish_cleaned_declarations(
    75	        &self,
    76	        cleaned: &CleanedDeclarations,
    77	    ) -> Result<(), EntitySearchPipelineError> {
    78	        let destination = self.cleaned_declarations_path();
    79	        if fs::try_exists(&destination).await.map_err(write_error)? {
    80	            return Err(write_error("cleaned declarations already exist"));
    81	        }
    82	        let parent = destination
    83	            .parent()
    84	            .expect("cleaned declarations have a parent");
    85	        fs::create_dir_all(parent).await.map_err(write_error)?;
    86	        let staging = parent.join(format!(".declarations-{}", Uuid::now_v7()));
    87	        fs::create_dir(&staging).await.map_err(write_error)?;
    88	        let result = async {
    89	            write_table(
    90	                &staging.join("funding_entries.parquet"),
    91	                funding_schema(),
    92	                &cleaned.funding_entries,
    93	            )
    94	            .await?;
    95	            write_table(
    96	                &staging.join("funders.parquet"),
    97	                funders_schema(),
    98	                &cleaned.funders,
    99	            )
   100	            .await?;
   101	            fs::rename(&staging, &destination)
   102	                .await
   103	                .map_err(write_error)
   104	        }
   105	        .await;
   106	        if result.is_err() {
   107	            let _ = fs::remove_dir_all(&staging).await;
   108	        }
   109	        result
   110	    }
   111	}
