   143	fn read_partition(path: &Path) -> Result<CapturedMemberDeclarations, EntitySearchPipelineError> {
   144	    let member_id = path
   145	        .file_stem()
   146	        .and_then(|name| name.to_str())
   147	        .ok_or_else(|| read_error("partition filename must contain a member UUID"))?
   148	        .parse::<Uuid>()
   149	        .map_err(read_error)?;
   150	    if member_id.is_nil() {
   151	        return Err(read_error("partition member UUID must not be nil"));
   152	    }
   153	    let reader = ParquetRecordBatchReaderBuilder::try_new(File::open(path).map_err(read_error)?)
   154	        .map_err(read_error)?;
   155	    if declarations_schema().fields().iter().any(|required| {
   156	        reader
   157	            .schema()
   158	            .field_with_name(required.name())
   159	            .map_or(true, |actual| {
   160	                actual.data_type() != required.data_type()
   161	                    || actual.is_nullable() != required.is_nullable()
   162	            })
   163	    }) {
   164	        return Err(read_error(
   165	            "raw declaration schema does not match the captured format",
   166	        ));
   167	    }
   168	    let mut groups = BTreeMap::<u32, Vec<RawDeclarationRecord>>::new();
   169	    let mut member = None;
   170	    for batch in reader.build().map_err(read_error)? {
   171	        let mut json = ArrayWriter::new(Vec::new());
   172	        json.write(&batch.map_err(read_error)?)
   173	            .map_err(read_error)?;
   174	        json.finish().map_err(read_error)?;
   175	        let rows: Vec<RawDeclarationRecord> =
   176	            serde_json::from_slice(&json.into_inner()).map_err(read_error)?;
   177	        for row in rows {
   178	            let identity =
   179	                MemberAsId::new(row.member_id, row.parliament_member_id).map_err(read_error)?;
   180	            if row.member_id != member_id || member.is_some_and(|member| member != identity) {
   181	                return Err(read_error(
   182	                    "partition member identity disagrees with its rows",
   183	                ));
   184	            }
   185	            member = Some(identity);
   186	            groups.entry(row.declaration_id).or_default().push(row);
   187	        }
   188	    }
   189	    let Some(member) = member else {
   190	        return Ok(CapturedMemberDeclarations::Empty { member_id });
   191	    };
   192	    let mut declarations = Vec::with_capacity(groups.len());
   193	    for (id, rows) in groups {
   194	        let first = &rows[0];
   195	        let source = serde_json::from_str(&first.source_json).map_err(read_error)?;
   196	        let evidence = replay_declaration(source, first.fetched_at).map_err(read_error)?;
   197	        let captured = evidence.declaration();
   198	        if rows
   199	            .iter()
   200	            .any(|row| row.source_json != first.source_json || !row.matches(captured))
   201	        {
   202	            return Err(read_error(format!(
   203	                "declaration {id}: source metadata disagrees with raw projection"
   204	            )));
   205	        }
   206	        let actual = funding_counts(rows.iter().map(|row| &row.funding));
   207	        let placeholder = CapturedFundingEntry::default();
   208	        let expected = if captured.funding_entries().is_empty() {
   209	            funding_counts([&placeholder])
   210	        } else {
   211	            funding_counts(captured.funding_entries())
   212	        };
   213	        if actual != expected {
   214	            return Err(read_error(format!(
   215	                "declaration {id}: funding multiplicity or values disagree with source"
   216	            )));
   217	        }
   218	        declarations.push(evidence);
   219	    }
   220	    Ok(CapturedMemberDeclarations::Populated {
   221	        member,
   222	        declarations,
   223	    })
   224	}
   225	
   226	fn funding_counts<'a>(
   227	    entries: impl IntoIterator<Item = &'a CapturedFundingEntry>,
   228	) -> HashMap<&'a CapturedFundingEntry, usize> {
   229	    let mut counts = HashMap::new();
   230	    for entry in entries {
   231	        *counts.entry(entry).or_insert(0) += 1;
   232	    }
   233	    counts
   234	}
   235	
   236	async fn write_table<T: Serialize + Sync>(
   237	    path: &Path,
   238	    schema: Schema,
   239	    rows: &[T],
   240	) -> Result<(), EntitySearchPipelineError> {
   241	    let file = fs::File::create_new(path).await.map_err(write_error)?;
   242	    let schema = Arc::new(schema);
   243	    let mut writer = AsyncArrowWriter::try_new(file, schema.clone(), None).map_err(write_error)?;
   244	    let mut decoder = ReaderBuilder::new(schema)
   245	        .build_decoder()
   246	        .map_err(write_error)?;
   247	    for chunk in rows.chunks(1024) {
   248	        decoder.serialize(chunk).map_err(write_error)?;
   249	        if let Some(batch) = decoder.flush().map_err(write_error)? {
   250	            writer.write(&batch).await.map_err(write_error)?;
   251	        }
   252	    }
   253	    writer.close().await.map_err(write_error)?;
   254	    Ok(())
   255	}
   256	
   257	fn funding_schema() -> Schema {
   258	    let mut fields = vec![
   259	        Field::new("funding_entry_id", DataType::Utf8, false),
   260	        Field::new("funding_ordinal", DataType::UInt32, false),
   261	        Field::new("donor_funder_id", DataType::Utf8, true),
   262	        Field::new("payer_funder_id", DataType::Utf8, true),
   263	        Field::new("ultimate_payer_funder_id", DataType::Utf8, true),
   264	    ];
   265	    fields.extend(
   266	        declarations_schema()
   267	            .fields()
   268	            .iter()
   269	            .filter(|field| field.name() != "source_json")
   270	            .map(|field| field.as_ref().clone()),
   271	    );
   272	    Schema::new(fields)
   273	}
   274	
   275	fn funders_schema() -> Schema {
   276	    let text = |name, nullable| Field::new(name, DataType::Utf8, nullable);
   277	    let list = |name| Field::new(name, DataType::List(Arc::new(text("item", false))), false);
   278	    Schema::new(vec![
   279	        text("funder_id", false),
   280	        text("member_id", false),
   281	        Field::new("declaration_id", DataType::UInt32, false),
   282	        Field::new("register_id", DataType::UInt32, false),
   283	        text("role", false),
   284	        text("source_scope", false),
   285	        text("source_pointer", false),
   286	        text("funding_entry_id", true),
   287	        Field::new("funding_ordinal", DataType::UInt32, true),
   288	        text("donor_kind", true),
   289	        text("donor_company_number", true),
   290	        text("name_raw", true),
   291	        text("name_status", false),
   292	        text("name_normalized", true),
   293	        text("name_accent_folded", true),
   294	        text("name_tokens", true),
   295	        text("name_token_key", true),
   296	        text("primary_name_normalized", true),
