    41	    /// Captures a complete dataset for the cohort read at the start of the run.
    42	    /// Runs up to ten member tasks concurrently, including their storage writes.
    43	    /// On failure, cancels and awaits the remaining tasks before returning.
    44	    ///
    45	    /// # Errors
    46	    /// Returns errors from the source or storage, task failures, or when no members are stored.
    47	    pub async fn fetch_declarations(&self) -> Result<IngestionKey, EntityIngestionError> {
    48	        let members = self.member_repo.get_stored_member_ids().await?;
    49	        if members.is_empty() {
    50	            return Err(EntityIngestionError::DataError(
    51	                "no stored members; load members with `data members load` before fetching declarations".into(),
    52	            ));
    53	        }
    54	        let mut members = members.into_iter();
    55	        let mut tasks = JoinSet::new();
    56	        loop {
    57	            while tasks.len() < MAX_CONCURRENT_MEMBERS {
    58	                let Some(member) = members.next() else {
    59	                    break;
    60	                };
    61	                let api = self.parliament_api.clone();
    62	                let storage = self.storage.clone();
    63	                tasks.spawn(async move {
    64	                    let declarations = api.get_declarations(member).await?;
    65	                    storage
    66	                        .write_raw_declarations(member, &declarations)
    67	                        .await?;
    68	                    Ok::<(), EntityIngestionError>(())
    69	                });
    70	            }
    71	            let Some(result) = tasks.join_next().await else {
    72	                break;
    73	            };
    74	            let result = result.unwrap_or_else(|error| {
    75	                Err(EntityIngestionError::UnexpectedError(format!(
    76	                    "declaration capture task failed: {error}"
    77	                )))
    78	            });
    79	            if let Err(error) = result {
    80	                tasks.shutdown().await;
    81	                return Err(error);
    82	            }
    83	        }
    84	        Ok(self.storage.ingestion_key())
    85	    }
    86	}
